umber(usdCny) : DEFAULT_USD_CNY;\n\t\t\treturn (n) => {\n\t\t\t\tconst v = Number(n) || 0;\n\t\t\t\treturn cur === 'usd' ? '$' + (v / rate).toFixed(4) : '¥' + v.toFixed(4);\n\t\t\t};\n\t\t}\n\n\t\tfunction fmtTime(ts) {\n\t\t\tconst n = Number(ts) || 0;\n\t\t\tif (n <= 0) return '—';\n\t\t\tconst d = new Date(n + 8 * 3600 * 1000);\n\t\t\tconst p = (x) => (x < 10 ? '0' + x : String(x));\n\t\t\treturn p(d.getUTCHours()) + ':' + p(d.getUTCMinutes()) + ':' + p(d.getUTCSeconds());\n\t\t}\n\n\t\tfunction fmtDateTime(ts) {\n\t\t\tconst n = Number(ts) || 0;\n\t\t\tif (n <= 0) return '—';\n\t\t\tconst d = new Date(n + 8 * 3600 * 1000);\n\t\t\tconst p = (x) => (x < 10 ? '0' + x : String(x));\n\t\t\tconst now = new Date(Date.now() + 8 * 3600 * 1000);\n\t\t\tconst date = (d.getUTCFullYear() === now.getUTCFullYear() ? '' : d.getUTCFullYear() + '-') + p(d.getUTCMonth() + 1) + '-' + p(d.getUTCDate());\n\t\t\treturn date + ' ' + p(d.getUTCHours()) + ':' + p(d.getUTCMinutes());\n\t\t}\n\n\t\tfunction shortId(id) {\n\t\t\tif (typeof id !== 'string') return T('common.unknown');\n\t\t\treturn id.length > 8 ? id.slice(0, 8) : id;\n\t\t}\n\n\t\tfunction el(type, props, ...children) {\n\t\t\treturn react.createElement(type, props || null, ...children);\n\t\t}\n\n\t\tconst CSS = `\n/* 语义色/阴影/圆角统一走宿主 token（带字面量兜底），使面板在明暗主题下与原生 UI 一致 */\n:root {\n  --usg-accent: var(--dsw-static-blue-450, #4d93f8);\n  --usg-accent-strong: var(--dsw-static-blue-500, #3b82f6);\n  --usg-accent-soft: var(--dsw-static-blue-300, #93c5fd);\n  --usg-neutral: var(--dsw-static-neutral-bluish-400, #adb2b8);\n  --usg-warn: var(--dsw-alias-state-warn-primary, #f59e0b);\n  --usg-error: var(--dsw-alias-state-error-primary, #ef4444);\n  --usg-ok: var(--dsw-alias-state-success-primary, #34d399);\n  --usg-band-before: var(--usg-neutral);\n  --usg-band-afterPeak: var(--usg-accent-strong);\n  --usg-band-afterOffPeak: var(--usg-accent-soft);\n  --usg-band-sepPeak: var(--dsw-static-violet-500, #8b5cf6);\n  --usg-band-sepOffPeak: 